        foreach(string l in new[]{"Việt + Anh","Tiếng Việt","Tiếng Anh"})language.Items.Add(l);language.SelectedIndex=0;Add("OCR",language);var ocr=new Button{Content="Nhận chữ lại"};var stop=new Button{Content="Dừng OCR",IsEnabled=false};ocr.Click+=async(_,_)=>{if(!Flush())return;ocr.IsEnabled=false;stop.IsEnabled=true;using var job=new CancellationTokenSource(TimeSpan.FromSeconds(120));ocrJob=job;try{if(Recognize!=null)await Recognize(Math.Max(0,language.SelectedIndex),job.Token);}finally{if(ReferenceEquals(ocrJob,job))ocrJob=null;ocr.IsEnabled=true;stop.IsEnabled=false;}};stop.Click+=(_,_)=>ocrJob?.Cancel();Children.Add(ocr);Children.Add(stop);
        foreach(string t in new[]{"Nền che","Nền control","Chữ","Viền"})pickTarget.Items.Add(t);pickTarget.SelectedIndex=2;Add("Lấy màu trên màn hình",pickTarget);var eye=new Button{Content="Lấy màu…"};eye.Click+=async(_,_)=>{Flush();if(PickScreen!=null)await PickScreen(pickTarget.SelectedIndex);};Children.Add(eye);
        Children.Add(preview);Children.Add(before);Children.Add(after);Children.Add(status);Children.Add(error);error.SetResourceReference(TextBlock.ForegroundProperty,"Danger");
        foreach(var t in new[]{text,size,padding,spacing,border,radius,ink,background,fill,stroke})t.TextChanged+=(_,_)=>Schedule();
        font.AddHandler(TextBox.TextChangedEvent,new TextChangedEventHandler((_,_)=>Schedule()));foreach(var c in new[]{kind,font,align,vertical})c.SelectionChanged+=(_,_)=>Schedule();foreach(var c in new[]{bold,italic,underline})c.Click+=(_,_)=>Schedule();
        timer.Tick+=(_,_)=>Flush();LostKeyboardFocus+=(_,_)=>Flush();preview.Click+=async(_,_)=>await Preview();Unloaded+=(_,_)=>{ocrJob?.Cancel();Flush();ReleasePreviews();};
    }
    void Add(string label,Control control){var target=control is TextBox input&&new[]{text,size,padding,spacing}.Contains(input)||control==font||control==align||control==vertical?typeTools:this;target.Children.Add(new TextBlock{Text=label,Margin=new(3,7,0,1)});target.Children.Add(control);}
    void Color(string title,TextBox field){typeTools.Children.Add(PropertyVisuals.ColorField(title,field,()=>PickColor?.Invoke()));}
    void Sample(){if(current==null)return;try{sample.Background=EditorRenderer.Ink(fill.Text);sample.BorderBrush=EditorRenderer.Ink(stroke.Text);sample.BorderThickness=new(Read(border,0,40));sample.CornerRadius=new(Read(radius,0,1000));sampleText.Text=text.Text.Length>0?text.Text:"Aa · Xem trước";sampleText.FontFamily=new FontFamily(font.Text.Length>0?font.Text:"Segoe UI");sampleText.FontSize=Math.Min(36,Read(size,8,240));sampleText.FontWeight=bold.IsChecked==true?FontWeights.Bold:FontWeights.Normal;sampleText.FontStyle=italic.IsChecked==true?FontStyles.Italic:FontStyles.Normal;sampleText.TextDecorations=underline.IsChecked==true?TextDecorations.Underline:null;sampleText.Foreground=EditorRenderer.Ink(ink.Text);sampleText.TextAlignment=EditorRenderer.WpfAlignment((TextAlign)Math.Max(0,align.SelectedIndex));bool label=current.Mockup?.Type is MockupKind.Label or MockupKind.Title;if(label){sample.Background=EditorRenderer.Ink(background.Text);sample.BorderThickness=new(0);}}catch{/* Incomplete field: keep last valid sample. */}}
    static string N(double n)=>n.ToString("R",CultureInfo.InvariantCulture);
    static double Read(TextBox t,double min,double max){if(!double.TryParse(t.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out var n)&&!double.TryParse(t.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out n)||!double.IsFinite(n)||n<min||n>max)throw new ArgumentException($"Giá trị cần từ {min} đến {max}.");return n;}
    public void Load(Annotation a){if(syncing)return;if(id!=a.Id){ocrJob?.Cancel();Flush();}id=a.Id;current=a.Copy();syncing=true;try{text.Text=a.Text;font.Text=a.FontFamily;size.Text=N(a.FontSize);bold.IsChecked=a.Bold;italic.IsChecked=a.Italic;underline.IsChecked=a.Underline;kind.SelectedIndex=(int)a.Mockup!.Type;align.SelectedIndex=(int)a.TextAlignment;vertical.SelectedIndex=(int)a.VerticalAlignment;padding.Text=N(a.TextPadding??0);spacing.Text=N(a.LineSpacing);ink.Text=a.TextColor??a.Color;background.Text=a.Mockup.Background;fill.Text=a.FillColor;stroke.Text=a.Color;border.Text=N(a.StrokeEnabled?a.Stroke:0);radius.Text=N(a.CornerRadius);IsEnabled=!a.Locked&&a.Visible;error.Text="";typeTools.Visibility=a.Mockup.Type is MockupKind.Label or MockupKind.Title||a.Text.Length>0?Visibility.Visible:Visibility.Collapsed;bodyTools.Visibility=a.Mockup.Type is MockupKind.Button or MockupKind.Input or MockupKind.Block?Visibility.Visible:Visibility.Collapsed;status.Text=a.Mockup.PreserveRaster?"Giữ nét chữ từ ảnh gốc. Font là gợi ý gần giống; chỉ thay hình thức khi Boss sửa.":"Đối tượng có thể chỉnh sửa · Ctrl+B / Ctrl+I / Ctrl+U.";}finally{syncing=false;}Sample();ReleasePreviews();preview.IsChecked=false;}
    public bool Flush(){timer.Stop();if(syncing||id==null||current==null)return true;try{
        var c=new MockupChanges(text.Text,font.Text,Read(size,8,240),bold.IsChecked==true,italic.IsChecked==true,underline.IsChecked==true,(TextAlign)align.SelectedIndex,(TextVertical)vertical.SelectedIndex,Read(padding,0,200),Read(spacing,0,3),ink.Text.Trim(),background.Text.Trim(),fill.Text.Trim(),stroke.Text.Trim(),Read(border,0,40),Read(radius,0,1000),(MockupKind)kind.SelectedIndex);
        var baseline=MockupEditing.Read(current);
        string SameColor(string value,string previous)=>string.Equals(value,previous,StringComparison.OrdinalIgnoreCase)?previous:value;
        c=c with{Font=string.Equals(c.Font.Trim(),baseline.Font.Trim(),StringComparison.OrdinalIgnoreCase)?baseline.Font:c.Font,Ink=SameColor(c.Ink,baseline.Ink),Background=SameColor(c.Background,baseline.Background),Fill=SameColor(c.Fill,baseline.Fill),Stroke=SameColor(c.Stroke,baseline.Stroke),Text=c.Text.Replace("\r\n","\n")==baseline.Text.Replace("\r\n","\n")?baseline.Text:c.Text};
        if(c!=baseline){syncing=true;try{Changed?.Invoke(id,c);}finally{syncing=false;}current.Text=c.Text;current.FontFamily=c.Font;current.FontSize=c.Size;current.Bold=c.Bold;current.Italic=c.Italic;current.Underline=c.Underline;current.TextColor=c.Ink;current.Mockup!.Background=c.Background;current.FillColor=c.Fill;current.Color=c.Stroke;current.StrokeEnabled=c.Border>0;current.Stroke=Math.Max(1,c.Border);current.CornerRadius=c.Radius;current.TextPadding=c.Padding;current.LineSpacing=c.Spacing;current.TextAlignment=c.Align;current.VerticalAlignment=c.Vertical;current.Mockup.Type=c.Kind;}
        error.Text="";return true;
